    pe, qe = p_even, 1.0 - p_even
    po, qo = p_odd, 1.0 - p_odd
    if pe <= 0 or qe <= 0 or po <= 0 or qo <= 0:
        return INF
    j_lo = max(0, k - n_even)
    j_hi = min(n_odd, k)
    if j_lo > j_hi:
        return INF
    best = INF
    expsum = 0.0
    # log-sum-exp accumulation
    for j in range(j_lo, j_hi + 1):
